"""Record all29terrain decisions, scoped evidence and unfinished construction."""
from pathlib import Path
import hashlib,json
ROOT=Path(__file__).resolve().parents[1];BASE=ROOT/'development/levels/rebuild/terrain-overall-pass'
def main():
    audit=json.loads((BASE/'terrain-envelopes.json').read_text());specs=json.loads((BASE/'macroterrain-specs.json').read_text())['sites'];fit=json.loads((BASE/'verification/native-route-fit.json').read_text())['sites'];rows=[]
    for site in audit['sites']:
        key=site['id'];folder=key.lower();candidate=key in specs
